/**
 * Lumenforge 0.4 visual contract: the Lantern Cabinet is an editable, local-first
 * story workshop. Midnight work surfaces, amber authored data, procedural paper-stage
 * elements, and direct author-to-preview flow reinforce the cinematic editorial direction.
 */
import { useEffect, useMemo, useRef, useState, type ChangeEvent } from "react";
import "../studio-v2.css";
import "../logic-workspace.css";
import "../inventory-workspace.css";
import "../expansion-workspaces.css";
import "../expanded-elements.css";
import "../new-project-dialog.css";
import {
  Aperture, Archive, ArrowRight, BookOpen, Box, Boxes, Braces, Check, ChevronRight, Clapperboard, Code2,
  Download, FileCode2, FilePlus2, Film, FolderOpen, Gamepad2, HelpCircle, Layers3, Lightbulb, MessageCircle,
  MonitorPlay, MousePointer2, Play, Plus, Save, Settings2, Sparkles, Trash2, Upload, Workflow, X,
  type LucideIcon,
} from "lucide-react";
import { toast } from "sonner";
import { BUILD_INFO } from "@/lib/buildInfo.generated";
import { AdvancedToolsPanel, AnimationPanel, DiyPanel, ThreeDPanel } from "@/components/ExpansionWorkspaces";
import {
  applyEffect, blocksToLua, conditionPasses, CORE_ELEMENT_KINDS, createBehaviourProgram, createElement, createEmptyProject, createStarterProject, sampleTrack,
  elementLabel, getActiveRoom, loadLocalProject, parseSupportedLua, runBehaviour, saveLocalProject, validateProject,
  PROCEDURAL_ELEMENTS, type BehaviourBlockKind, type Choice, type Cutscene, type CutsceneShot, type ElementKind, type LumenProject,
  type LumenItem, type LumenRoom, type NarrativeNode, type ProjectVariable, type SceneElement, type StoryNodeKind, type VariableType,
  type ProjectMode,
} from "@/lib/studioProject";

type ScreenMode = "project" | "room" | "inventory" | "narrative" | "state" | "cutscene" | "scripts" | "animation" | "diy" | "threeD" | "advanced" | "build";
type Tone = SceneElement["tone"];

const nav: Array<{ id: ScreenMode; label: string; icon: LucideIcon; shortcut: string }> = [
  { id: "project", label: "Project", icon: Archive, shortcut: "0" },
  { id: "room", label: "Rooms", icon: Aperture, shortcut: "1" },
  { id: "inventory", label: "Items", icon: Boxes, shortcut: "2" },
  { id: "narrative", label: "Story", icon: MessageCircle, shortcut: "3" },
  { id: "state", label: "State", icon: Braces, shortcut: "4" },
  { id: "cutscene", label: "Cutscene", icon: Film, shortcut: "5" },
  { id: "scripts", label: "Logic", icon: Code2, shortcut: "6" },
  { id: "animation", label: "Animation", icon: Workflow, shortcut: "7" },
  { id: "diy", label: "DIY", icon: Sparkles, shortcut: "8" },
  { id: "threeD", label: "3D Mode", icon: Layers3, shortcut: "9" },
  { id: "advanced", label: "Tool Suite", icon: Settings2, shortcut: "+" },
  { id: "build", label: "Export", icon: Gamepad2, shortcut: "0" },
];

const DESKTOP_RELEASE = BUILD_INFO.release;
type ReleaseEvidence = { sourceRevision: string; bundleSha256: string; generatedAt: string; nativeSourceRevision: string; buildChannel: string };
const initialReleaseEvidence: ReleaseEvidence = { sourceRevision: BUILD_INFO.sourceRevision, bundleSha256: "not-generated", generatedAt: BUILD_INFO.generatedAt, nativeSourceRevision: "web-preview", buildChannel: "development" };

const elementKinds: ElementKind[] = PROCEDURAL_ELEMENTS.map(([kind]) => kind);
const moods: Array<{ value: LumenRoom["ambience"]; label: string; detail: string }> = [
  { value: "afterhours", label: "Afterhours", detail: "blue-black quiet" }, { value: "mauve", label: "Mauve signal", detail: "faded emotional violet" },
  { value: "morning", label: "Morning proof", detail: "cold hopeful daylight" }, { value: "rain", label: "Rain chamber", detail: "wet slate and silver" }, { value: "ember", label: "Ember rehearsal", detail: "small warm danger" },
];

function Monogram() {
  return <div className="brand-mark" aria-label="Lumenforge mark"><span className="brand-mark-fallback" aria-hidden="true"><i /><b /></span></div>;
}

function downloadJson(name: string, data: unknown) {
  const url = URL.createObjectURL(new Blob([JSON.stringify(data, null, 2)], { type: "application/json" }));
  const anchor = document.createElement("a"); anchor.href = url; anchor.download = name; anchor.click(); URL.revokeObjectURL(url);
}

function slug(value: string) { return value.toLowerCase().trim().replace(/[^a-z0-9]+/g, "-").replace(/(^-|-$)/g, "") || "lumenforge-game"; }
function makeId(prefix: string) { return `${prefix}-${Math.random().toString(36).slice(2, 8)}`; }

function RailButton({ item, active, onClick }: { item: (typeof nav)[number]; active: boolean; onClick: () => void }) {
  const Icon = item.icon;
  return <button className={`rail-button ${active ? "is-active" : ""}`} onClick={onClick} title={`${item.label} (${item.shortcut})`}><Icon size={17} /><span>{item.label}</span><kbd>{item.shortcut}</kbd></button>;
}

function Field({ label, children }: { label: string; children: React.ReactNode }) { return <label className="forge-field"><span>{label}</span>{children}</label>; }
function TinyButton({ children, onClick, title, tone = "quiet" }: { children: React.ReactNode; onClick: () => void; title?: string; tone?: "quiet" | "amber" | "danger" }) { return <button className={`tiny-button ${tone}`} onClick={onClick} title={title}>{children}</button>; }

type RuntimeMotion = Partial<Record<"x" | "y" | "z" | "rotation" | "scale" | "opacity", number>>;
function SceneCanvas({ room, selectedId, onSelect, playable = false, onActivate, animatedIds, motion }: { room: LumenRoom; selectedId?: string; onSelect?: (id: string) => void; playable?: boolean; onActivate?: (element: SceneElement) => void; animatedIds?: Set<string>; motion?: Record<string, RuntimeMotion> }) {
  return <div className={`lumen-stage ambience-${room.ambience} ${playable ? "is-playable" : ""}`}>
    <div className="stage-grain" /><div className="stage-stars" aria-hidden="true">{Array.from({ length: 24 }).map((_, index) => <i key={index} style={{ "--i": index } as React.CSSProperties} />)}</div>
    <div className="stage-horizon" aria-hidden="true" /><div className="stage-safety" aria-hidden="true"><span>{room.mark} · 16:9</span></div>
    {room.elements.filter((element) => element.visible).sort((a, b) => a.layer.localeCompare(b.layer)).map((element) => {
      const current = motion?.[element.id]; const interactive = element.interaction.type !== "none" || Boolean(element.collectibleItemId) || Boolean(animatedIds?.has(element.id));
      return <button key={element.id} className={`scene-piece kind-${element.kind} tone-${element.tone} ${selectedId === element.id ? "is-selected" : ""} ${interactive ? "is-interactive" : ""}`} style={{ left: `${current?.x ?? element.x}%`, top: `${current?.y ?? element.y}%`, opacity: current?.opacity ?? 1, "--piece-scale": (current?.scale ?? 1) * element.scale, "--piece-rotate": `${current?.rotation ?? 0}deg` } as React.CSSProperties}
        onClick={() => { onSelect?.(element.id); if (playable && interactive) onActivate?.(element); }} title={playable && interactive ? `${element.label} — play interaction` : element.label}>
        <span className={`piece-drawing ${CORE_ELEMENT_KINDS.includes(element.kind as typeof CORE_ELEMENT_KINDS[number]) ? "" : "is-extended"}`} aria-hidden="true"><i /><b /><em /></span><small>{element.label}</small>
      </button>;
    })}
    {room.elements.length === 0 && <div className="stage-empty"><Box size={25} /><b>This room is empty.</b><span>Add an element from the Scene Kit to begin.</span></div>}
  </div>;
}

function ProjectPanel({ project, update, onEmpty, onStarter, onImport, onExport, onOpenRooms }: { project: LumenProject; update: (patch: Partial<LumenProject>) => void; onEmpty: (mode: ProjectMode) => void; onStarter: () => void; onImport: () => void; onExport: () => void; onOpenRooms: () => void }) {
  const validation = validateProject(project);
  return <main className="creator-page project-page">
    <section className="project-hero"><div className="project-hero-copy"><span className="eyebrow">Lumenforge project room · local-first · {project.mode} narrative</span><h1>Build a small world that <i>answers back.</i></h1><p>Choose 2D Narrative for paper-stage storycraft or 3D Narrative for locally-generated primitive scenes. Every room, prop, choice, cutscene and rule is saved inside this project.</p><div className="hero-actions"><button className="amber-button" onClick={onOpenRooms}><Aperture size={16} /> Shape the first room</button><button className="outline-button" onClick={() => onEmpty("2d")}><FilePlus2 size={16} /> New 2D project</button><button className="outline-button" onClick={() => onEmpty("3d")}><Layers3 size={16} /> New 3D project</button></div></div><div className="project-sigil" aria-hidden="true"><span /><span /><span /><b>{project.mode === "3d" ? "3" : "L"}</b></div></section>
    <section className="project-workbench">
      <article className="work-card title-card"><div className="card-title"><BookOpen size={15} /><span>Project identity</span></div><Field label="Title"><input value={project.title} onChange={(event) => update({ title: event.target.value, id: slug(event.target.value), build: { ...project.build, executableName: slug(event.target.value) } })} placeholder="Name your adventure" /></Field><Field label="Premise"><textarea value={project.premise} onChange={(event) => update({ premise: event.target.value })} placeholder="What strange promise does this story make?" /></Field><div className="project-id"><span>{project.mode} narrative · project id</span><code>{project.id}</code></div></article>
      <article className="work-card health-card"><div className="card-title"><Workflow size={15} /><span>Authoring pulse</span></div><b className="health-number">{validation.score}<small>/100</small></b><p>{validation.errors.length ? `${validation.errors.length} blocking issue(s) need care before release.` : "Your local project has no blocking reference errors."}</p><div className="health-stats"><span>{project.rooms.length} rooms</span><span>{project.narrative.length} nodes</span><span>{project.cutscenes.length} cutscenes</span></div></article>
      <article className="work-card start-card"><div className="card-title"><Sparkles size={15} /><span>Start here</span></div><p>Want a guided original example to deconstruct? Load the starter project, then change every part of it.</p><button className="text-button" onClick={onStarter}>Load “The Lantern Under the Hill” <ChevronRight size={15} /></button><div className="portable-actions"><button onClick={onExport}><Download size={14} /> Export JSON</button><button onClick={onImport}><Upload size={14} /> Import JSON</button></div></article>
    </section>
    <section className="creation-route"><div className="route-heading"><span>Simple creation route</span><small>Each step edits the same project.</small></div>{[["1", "Rooms", "Compose locations and procedural props", Aperture], ["2", "Story", "Write choices and consequences", MessageCircle], ["3", "Cutscene", "Direct shots and transitions", Film], ["4", "Export", "Validate a release-ready package", Gamepad2]].map(([n, label, detail, Icon]) => { const RouteIcon = Icon as LucideIcon; return <button onClick={onOpenRooms} className="route-step" key={label as string}><b>{n as string}</b><RouteIcon size={18} /><span><small>{label as string}</small><em>{detail as string}</em></span><ArrowRight size={15} /></button>; })}</section>
  </main>;
}

function RoomPanel({ project, update, selectedId, setSelectedId, onAddRoom, onDuplicateRoom, onDeleteRoom }: { project: LumenProject; update: (next: LumenProject) => void; selectedId?: string; setSelectedId: (id?: string) => void; onAddRoom: () => void; onDuplicateRoom: () => void; onDeleteRoom: () => void }) {
  const room = getActiveRoom(project); const selected = room.elements.find((element) => element.id === selectedId);
  const updateRoom = (patch: Partial<LumenRoom>) => update({ ...project, rooms: project.rooms.map((candidate) => candidate.id === room.id ? { ...candidate, ...patch } : candidate) });
  const updateElement = (patch: Partial<SceneElement>) => selected && updateRoom({ elements: room.elements.map((element) => element.id === selected.id ? { ...element, ...patch } : element) });
  const addElement = (kind: ElementKind) => { const element = createElement(kind, room.elements.length); updateRoom({ elements: [...room.elements, element] }); setSelectedId(element.id); toast.success(`${element.label} added to ${room.name}.`); };
  const removeElement = () => { if (!selected) return; updateRoom({ elements: room.elements.filter((element) => element.id !== selected.id) }); setSelectedId(undefined); toast.message("Element removed from this room."); };
  const interactionTargets = selected?.interaction.type === "story" ? project.narrative.map((node) => ({ id: node.id, name: node.title })) : selected?.interaction.type === "room" ? project.rooms.map((candidate) => ({ id: candidate.id, name: candidate.name })) : selected?.interaction.type === "cutscene" ? project.cutscenes.map((cutscene) => ({ id: cutscene.id, name: cutscene.title })) : [];
  return <main className="creator-page room-page"><section className="page-heading"><div><span className="eyebrow">Room compositor · persistent scene data</span><h1>Give the room something to remember.</h1></div><button className="amber-button" onClick={() => addElement("actor")}><Plus size={16} /> Add character</button></section><section className="room-layout">
    <aside className="room-sidebar"><div className="panel-label"><span>Rooms</span><TinyButton onClick={onAddRoom} title="Create room" tone="amber"><Plus size={14} /></TinyButton></div><div className="room-list">{project.rooms.map((candidate) => <button className={`room-switch ${candidate.id === room.id ? "is-current" : ""}`} onClick={() => { update({ ...project, activeRoom: candidate.id }); setSelectedId(undefined); }} key={candidate.id}><b>{candidate.mark}</b><span>{candidate.name}<small>{candidate.elements.length} elements · {candidate.ambience}</small></span></button>)}</div><div className="sidebar-actions"><button onClick={onDuplicateRoom}><Layers3 size={14} /> Duplicate room</button><button onClick={onDeleteRoom} disabled={project.rooms.length < 2}><Trash2 size={14} /> Remove room</button></div><div className="room-settings"><Field label="Room name"><input value={room.name} onChange={(event) => updateRoom({ name: event.target.value })} /></Field><Field label="Atmosphere"><select value={room.ambience} onChange={(event) => updateRoom({ ambience: event.target.value as LumenRoom["ambience"] })}>{moods.map((mood) => <option value={mood.value} key={mood.value}>{mood.label} — {mood.detail}</option>)}</select></Field><Field label="Entry story node"><select value={room.entryNode} onChange={(event) => updateRoom({ entryNode: event.target.value })}><option value="">No dialogue on entry</option>{project.narrative.map((node) => <option value={node.id} key={node.id}>{node.title}</option>)}</select></Field></div></aside>
    <section className="stage-shell"><div className="stage-header"><span><i /> {room.name}</span><small>click an element to edit it · all art generated locally</small></div><SceneCanvas room={room} selectedId={selectedId} onSelect={setSelectedId} /><div className="scene-kit"><div><span className="eyebrow">Scene kit</span><b>Insert a procedural element</b></div><div className="scene-kit-options">{elementKinds.map((kind) => <button onClick={() => addElement(kind)} key={kind} title={`Add ${elementLabel[kind]}`}><i className={`kit-glyph kind-${kind}`} /><span>{elementLabel[kind]}</span></button>)}</div></div></section>
    <aside className="element-inspector">{selected ? <><div className="panel-label"><span>Element inspector</span><TinyButton onClick={removeElement} tone="danger" title="Delete element"><Trash2 size={14} /></TinyButton></div><div className="selected-element-title"><i className={`kit-glyph kind-${selected.kind}`} /><div><small>{selected.kind} · {selected.layer}</small><b>{selected.label}</b></div></div><Field label="Visible label"><input value={selected.label} onChange={(event) => updateElement({ label: event.target.value })} /></Field><div className="inline-fields"><Field label="X"><input type="number" min="0" max="100" value={Math.round(selected.x)} onChange={(event) => updateElement({ x: Number(event.target.value) })} /></Field><Field label="Y"><input type="number" min="0" max="100" value={Math.round(selected.y)} onChange={(event) => updateElement({ y: Number(event.target.value) })} /></Field></div><Field label={`Scale · ${selected.scale.toFixed(1)}×`}><input type="range" min="0.4" max="2" step="0.1" value={selected.scale} onChange={(event) => updateElement({ scale: Number(event.target.value) })} /></Field><div className="inline-fields"><Field label="Tone"><select value={selected.tone} onChange={(event) => updateElement({ tone: event.target.value as Tone })}>{["amber", "sage", "coral", "ivory", "ink"].map((tone) => <option value={tone} key={tone}>{tone}</option>)}</select></Field><Field label="Layer"><select value={selected.layer} onChange={(event) => updateElement({ layer: event.target.value as SceneElement["layer"] })}>{["sky", "backdrop", "props", "actors", "foreground"].map((layer) => <option value={layer} key={layer}>{layer}</option>)}</select></Field></div><label className="visibility-check"><input type="checkbox" checked={selected.visible} onChange={(event) => updateElement({ visible: event.target.checked })} /> Draw this element in the game</label><div className="inspector-divider" /><Field label="When clicked"><select value={selected.interaction.type} onChange={(event) => updateElement({ interaction: { type: event.target.value as SceneElement["interaction"]["type"], target: "" } })}><option value="none">No interaction</option><option value="story">Open story node</option><option value="room">Move to another room</option><option value="cutscene">Play a cutscene</option></select></Field>{selected.interaction.type !== "none" && <><Field label="Destination"><select value={selected.interaction.target} onChange={(event) => updateElement({ interaction: { ...selected.interaction, target: event.target.value } })}><option value="">Choose a destination</option>{interactionTargets.map((target) => <option value={target.id} key={target.id}>{target.name}</option>)}</select></Field><Field label="Only when condition passes"><input value={selected.interaction.condition ?? ""} onChange={(event) => updateElement({ interaction: { ...selected.interaction, condition: event.target.value } })} placeholder="lamp_awake == true" /></Field></>}</> : <div className="inspector-empty"><MousePointer2 size={25} /><b>Select a piece on the stage.</b><p>Then change its label, position, colour, layer, visibility and game interaction here.</p></div>}</aside>
  </section></main>;
}

function InventoryPanel({ project, update, onOpenRooms }: { project: LumenProject; update: (next: LumenProject) => void; onOpenRooms: () => void }) {
  const [selectedId, setSelectedId] = useState<string | undefined>(project.items[0]?.id);
  const selected = project.items.find((item) => item.id === selectedId) ?? project.items[0];
  const updateItem = (patch: Partial<LumenItem>) => selected && update({ ...project, items: project.items.map((item) => item.id === selected.id ? { ...item, ...patch } : item) });
  const addItem = () => { const item: LumenItem = { id: makeId("item"), name: "New item", description: "What does this object quietly mean?", category: "clue", tone: "amber", icon: "note" }; update({ ...project, items: [...project.items, item] }); setSelectedId(item.id); };
  const removeItem = () => { if (!selected) return; const rooms = project.rooms.map((room) => ({ ...room, elements: room.elements.map((element) => element.collectibleItemId === selected.id ? { ...element, collectibleItemId: "" } : element) })); const behaviours = project.behaviours.map((program) => ({ ...program, blocks: program.blocks.filter((block) => !(block.kind === "give_item" && block.target === selected.id)) })); update({ ...project, rooms, behaviours, items: project.items.filter((item) => item.id !== selected.id), inventory: { ...project.inventory, itemIds: project.inventory.itemIds.filter((id) => id !== selected.id) } }); setSelectedId(project.items.find((item) => item.id !== selected.id)?.id); };
  const locations = project.rooms.flatMap((room) => room.elements.map((element) => ({ room, element }))).filter(({ element }) => element.kind === "note" || element.kind === "table" || element.kind === "mirror" || element.kind === "sign" || element.kind === "lamp");
  const setCollectible = (roomId: string, elementId: string, checked: boolean) => { if (!selected) return; update({ ...project, rooms: project.rooms.map((room) => room.id === roomId ? { ...room, elements: room.elements.map((element) => element.id === elementId ? { ...element, collectibleItemId: checked ? selected.id : "" } : element) } : room) }); };
  return <main className="creator-page inventory-page"><section className="page-heading"><div><span className="eyebrow">Item cabinet · collectables and player inventory</span><h1>Let the player carry a small piece of the world.</h1></div><div className="heading-actions"><button className="outline-button" onClick={onOpenRooms}><Aperture size={15} /> Place items in rooms</button><button className="amber-button" onClick={addItem}><Plus size={16} /> New item</button></div></section><section className="inventory-layout"><aside className="item-list"><div className="panel-label"><span>Item library</span><span>{project.items.length}</span></div>{project.items.length === 0 && <p className="empty-copy">Create a key, clue, keepsake, tool or token. Then place it on an authored prop.</p>}{project.items.map((item) => <button className={selected?.id === item.id ? "is-current" : ""} onClick={() => setSelectedId(item.id)} key={item.id}><i className={`kit-glyph kind-${item.icon}`} /><span>{item.name}<small>{item.category} · {item.id}</small></span></button>)}</aside>{selected ? <><section className="item-editor"><div className="panel-label"><span>Item editor</span><TinyButton tone="danger" title="Delete item" onClick={removeItem}><Trash2 size={14} /></TinyButton></div><div className="item-identity"><i className={`kit-glyph kind-${selected.icon}`} /><div><small>{selected.category}</small><b>{selected.name}</b></div></div><Field label="Item name"><input value={selected.name} onChange={(event) => updateItem({ name: event.target.value })} /></Field><Field label="Stable item id"><input value={selected.id} onChange={(event) => updateItem({ id: event.target.value.replace(/\s+/g, "-") })} /></Field><Field label="Description"><textarea value={selected.description} onChange={(event) => updateItem({ description: event.target.value })} /></Field><div className="inline-fields"><Field label="Category"><select value={selected.category} onChange={(event) => updateItem({ category: event.target.value as LumenItem["category"] })}>{["key", "clue", "keepsake", "tool", "token"].map((category) => <option value={category} key={category}>{category}</option>)}</select></Field><Field label="Object drawing"><select value={selected.icon} onChange={(event) => updateItem({ icon: event.target.value as ElementKind })}>{elementKinds.map((kind) => <option value={kind} key={kind}>{elementLabel[kind]}</option>)}</select></Field></div><Field label="Inventory tone"><select value={selected.tone} onChange={(event) => updateItem({ tone: event.target.value as Tone })}>{["amber", "sage", "coral", "ivory", "ink"].map((tone) => <option value={tone} key={tone}>{tone}</option>)}</select></Field></section><section className="item-placement"><div className="panel-label"><span>Place this item in the world</span><small>{locations.filter(({ element }) => element.collectibleItemId === selected.id).length} placement(s)</small></div><p>Choose a prop in any authored scenario. In preview, clicking that prop adds this item to the inventory and then follows its optional interaction.</p><div className="placement-list">{locations.map(({ room, element }) => <label key={element.id} className={element.collectibleItemId === selected.id ? "is-linked" : ""}><input type="checkbox" checked={element.collectibleItemId === selected.id} onChange={(event) => setCollectible(room.id, element.id, event.target.checked)} /><i className={`kit-glyph kind-${element.kind}`} /><span>{room.name} / {element.label}<small>{element.interaction.type === "none" ? "collect only" : `${element.interaction.type} after collection`}</small></span></label>)}</div><div className="inventory-settings"><Field label="Maximum inventory slots"><input type="number" min="1" max="99" value={project.inventory.maxSlots} onChange={(event) => update({ ...project, inventory: { ...project.inventory, maxSlots: Number(event.target.value) } })} /></Field><div><span className="eyebrow">Current test inventory</span><p>{project.inventory.itemIds.length ? project.inventory.itemIds.map((id) => project.items.find((item) => item.id === id)?.name ?? id).join(" · ") : "Empty — collect items in the playable preview."}</p></div></div></section></> : <section className="inventory-empty"><Boxes size={30} /><h2>Build a pocket of meaningful things.</h2><p>Items can be collected from props, used in conditions, awarded by visual blocks or Lua, and carried between all scenarios.</p></section>}</section></main>;
}

function NarrativePanel({ project, update, selectedId, setSelectedId, onPreview }: { project: LumenProject; update: (next: LumenProject) => void; selectedId?: string; setSelectedId: (id?: string) => void; onPreview: () => void }) {
  const selected = project.narrative.find((node) => node.id === selectedId) ?? project.narrative[0];
  const updateNode = (patch: Partial<NarrativeNode>) => update({ ...project, narrative: project.narrative.map((node) => node.id === selected.id ? { ...node, ...patch } : node) });
  const addNode = (kind: StoryNodeKind) => { const node: NarrativeNode = { id: makeId(kind), kind, title: `New ${kind}`, speaker: "", body: "Write what happens here.", target: "", effect: "", condition: "", choices: [], x: 15 + ((project.narrative.length * 19) % 70), y: 18 + ((project.narrative.length * 21) % 68) }; update({ ...project, narrative: [...project.narrative, node] }); setSelectedId(node.id); toast.success(`${kind} node added to the story map.`); };
  const deleteNode = () => { if (project.narrative.length <= 1 || selected.kind === "start") return toast.error("Keep at least one start node in the project."); update({ ...project, narrative: project.narrative.filter((node) => node.id !== selected.id).map((node) => ({ ...node, target: node.target === selected.id ? "" : node.target, choices: node.choices.map((choice) => choice.target === selected.id ? { ...choice, target: "" } : choice) })) }); setSelectedId(project.narrative[0]?.id); };
  const updateChoice = (choiceId: string, patch: Partial<Choice>) => updateNode({ choices: selected.choices.map((choice) => choice.id === choiceId ? { ...choice, ...patch } : choice) });
  const addChoice = () => updateNode({ choices: [...selected.choices, { id: makeId("choice"), text: "A new choice", target: "" }] });
  return <main className="creator-page narrative-page"><section className="page-heading"><div><span className="eyebrow">Story graph · text, choices and consequences</span><h1>Every choice should leave a small mark.</h1></div><div className="heading-actions"><button className="outline-button" onClick={onPreview}><Play size={15} /> Test story</button><button className="amber-button" onClick={() => addNode("dialogue")}><Plus size={16} /> Add node</button></div></section><section className="story-layout"><section className="story-map"><div className="map-grid" aria-hidden="true" />{project.narrative.map((node) => <button key={node.id} className={`story-card kind-${node.kind} ${selected.id === node.id ? "is-current" : ""}`} style={{ left: `${node.x}%`, top: `${node.y}%` }} onClick={() => setSelectedId(node.id)}><small>{node.kind}</small><b>{node.title || "Untitled node"}</b><span>{node.body || "No text yet"}</span></button>)}<div className="story-map-controls"><button onClick={() => addNode("choice")}><Plus size={14} /> Choice</button><button onClick={() => addNode("consequence")}><Plus size={14} /> Consequence</button><button onClick={() => addNode("ending")}><Plus size={14} /> Ending</button></div></section><aside className="node-inspector"><div className="panel-label"><span>Node editor</span><TinyButton onClick={deleteNode} tone="danger" title="Delete selected node"><Trash2 size={14} /></TinyButton></div><Field label="Node kind"><select value={selected.kind} onChange={(event) => updateNode({ kind: event.target.value as StoryNodeKind })}>{["start", "dialogue", "choice", "consequence", "ending"].map((kind) => <option value={kind} key={kind}>{kind}</option>)}</select></Field><Field label="Working title"><input value={selected.title} onChange={(event) => updateNode({ title: event.target.value })} /></Field><Field label="Speaker"><input value={selected.speaker ?? ""} onChange={(event) => updateNode({ speaker: event.target.value })} placeholder="Mira, Narrator, The House…" /></Field><Field label="Line or story text"><textarea value={selected.body} onChange={(event) => updateNode({ body: event.target.value })} /></Field>{selected.kind !== "choice" && selected.kind !== "ending" && <Field label="Continue to"><select value={selected.target ?? ""} onChange={(event) => updateNode({ target: event.target.value })}><option value="">Stop here</option>{project.narrative.filter((node) => node.id !== selected.id).map((node) => <option value={node.id} key={node.id}>{node.title}</option>)}</select></Field>}<Field label="Only when condition passes"><input value={selected.condition ?? ""} onChange={(event) => updateNode({ condition: event.target.value })} placeholder="dream_count >= 2" /></Field><Field label="Effect on arrival"><input value={selected.effect ?? ""} onChange={(event) => updateNode({ effect: event.target.value })} placeholder="lamp_awake = true" /></Field>{selected.kind === "choice" && <section className="choice-editor"><div className="panel-label"><span>Player choices</span><TinyButton onClick={addChoice} tone="amber" title="Add choice"><Plus size={14} /></TinyButton></div>{selected.choices.length === 0 && <p className="empty-copy">Add at least one player response.</p>}{selected.choices.map((choice) => <article className="choice-row" key={choice.id}><input value={choice.text} onChange={(event) => updateChoice(choice.id, { text: event.target.value })} /><select value={choice.target} onChange={(event) => updateChoice(choice.id, { target: event.target.value })}><option value="">Destination</option>{project.narrative.filter((node) => node.id !== selected.id).map((node) => <option value={node.id} key={node.id}>{node.title}</option>)}</select><input value={choice.effect ?? ""} onChange={(event) => updateChoice(choice.id, { effect: event.target.value })} placeholder="optional effect" /><button onClick={() => updateNode({ choices: selected.choices.filter((candidate) => candidate.id !== choice.id) })}><X size={14} /></button></article>)}</section>}</aside></section></main>;
}

function StatePanel({ project, update }: { project: LumenProject; update: (next: LumenProject) => void }) {
  const [selectedId, setSelectedId] = useState(project.variables[0]?.id); const [expression, setExpression] = useState("lamp_awake == true"); const selected = project.variables.find((variable) => variable.id === selectedId) ?? project.variables[0];
  const updateVariable = (patch: Partial<ProjectVariable>) => selected && update({ ...project, variables: project.variables.map((variable) => variable.id === selected.id ? { ...variable, ...patch } : variable) });
  const addVariable = () => { const variable: ProjectVariable = { id: makeId("state"), key: "new_fact", type: "boolean", value: false, usedBy: [] }; update({ ...project, variables: [...project.variables, variable] }); setSelectedId(variable.id); };
  return <main className="creator-page state-page"><section className="page-heading"><div><span className="eyebrow">State ledger · typed consequences</span><h1>Small facts make the world remember.</h1></div><button className="amber-button" onClick={addVariable}><Plus size={16} /> New variable</button></section><section className="state-layout"><section className="variable-ledger"><div className="ledger-head"><span>Variable</span><span>Type</span><span>Current value</span><span>References</span></div>{project.variables.map((variable) => <button onClick={() => setSelectedId(variable.id)} className={`variable-row ${selected?.id === variable.id ? "is-current" : ""}`} key={variable.id}><span><i className={`var-dot ${variable.type}`} />{variable.key}</span><em>{variable.type}</em><b>{String(variable.value)}</b><small>{variable.usedBy.length || "not wired"}</small></button>)}</section><aside className="state-inspector">{selected && <><div className="panel-label"><span>Variable editor</span><TinyButton tone="danger" title="Delete variable" onClick={() => { if (project.variables.length <= 1) return toast.error("Keep at least one state variable."); update({ ...project, variables: project.variables.filter((variable) => variable.id !== selected.id) }); setSelectedId(project.variables[0]?.id); }}><Trash2 size={14} /></TinyButton></div><Field label="Key"><input value={selected.key} onChange={(event) => updateVariable({ key: event.target.value.replace(/\s+/g, "_") })} /></Field><Field label="Type"><select value={selected.type} onChange={(event) => { const type = event.target.value as VariableType; updateVariable({ type, value: type === "boolean" ? false : type === "integer" ? 0 : "" }); }}><option value="boolean">boolean</option><option value="integer">integer</option><option value="string">string</option></select></Field><Field label="Current value">{selected.type === "boolean" ? <select value={String(selected.value)} onChange={(event) => updateVariable({ value: event.target.value === "true" })}><option value="true">true</option><option value="false">false</option></select> : <input type={selected.type === "integer" ? "number" : "text"} value={String(selected.value)} onChange={(event) => updateVariable({ value: selected.type === "integer" ? Number(event.target.value) : event.target.value })} />}</Field><div className="state-reference"><span>Used by</span><p>{selected.usedBy.length ? selected.usedBy.join(" · ") : "No authored reference has claimed this yet."}</p></div></>}</aside></section><section className="condition-tester"><div><span className="eyebrow">Condition tester</span><h2>Ask the project a real question.</h2></div><input value={expression} onChange={(event) => setExpression(event.target.value)} placeholder="lamp_awake == true" /><span className={conditionPasses(project, expression) ? "condition-result passes" : "condition-result fails"}>{conditionPasses(project, expression) ? <><Check size={15} /> passes</> : <><X size={15} /> does not pass</>}</span></section></main>;
}

function CutscenePanel({ project, update, onPreview }: { project: LumenProject; update: (next: LumenProject) => void; onPreview: (cutsceneId: string) => void }) {
  const [selectedId, setSelectedId] = useState<string | undefined>(project.cutscenes[0]?.id); const [shotId, setShotId] = useState<string | undefined>(project.cutscenes[0]?.shots[0]?.id); const selected = project.cutscenes.find((cutscene) => cutscene.id === selectedId) ?? project.cutscenes[0]; const shot = selected?.shots.find((candidate) => candidate.id === shotId) ?? selected?.shots[0];
  const updateCutscene = (patch: Partial<Cutscene>) => selected && update({ ...project, cutscenes: project.cutscenes.map((cutscene) => cutscene.id === selected.id ? { ...cutscene, ...patch } : cutscene) });
  const updateShot = (patch: Partial<CutsceneShot>) => shot && updateCutscene({ shots: selected.shots.map((candidate) => candidate.id === shot.id ? { ...candidate, ...patch } : candidate) });
  const addCutscene = () => { const cutscene: Cutscene = { id: makeId("cutscene"), title: "New cutscene", trigger: "manual", triggerTarget: "", shots: [] }; update({ ...project, cutscenes: [...project.cutscenes, cutscene] }); setSelectedId(cutscene.id); setShotId(undefined); };
  const addShot = () => { if (!selected) return; const newShot: CutsceneShot = { id: makeId("shot"), label: `Shot ${selected.shots.length + 1}`, roomId: project.activeRoom, camera: "medium", transition: "cut", duration: 2, line: "", speaker: "" }; updateCutscene({ shots: [...selected.shots, newShot] }); setShotId(newShot.id); };
  return <main className="creator-page cutscene-page"><section className="page-heading"><div><span className="eyebrow">Cutscene director · shots, lines and transitions</span><h1>Direct the silence between choices.</h1></div><button className="amber-button" onClick={addCutscene}><Plus size={16} /> New cutscene</button></section><section className="cutscene-layout"><aside className="cutscene-list"><div className="panel-label"><span>Sequences</span></div>{project.cutscenes.length === 0 && <p className="empty-copy">Create a sequence to begin directing.</p>}{project.cutscenes.map((cutscene) => <button className={selected?.id === cutscene.id ? "is-current" : ""} onClick={() => { setSelectedId(cutscene.id); setShotId(cutscene.shots[0]?.id); }} key={cutscene.id}><Film size={15} /><span>{cutscene.title}<small>{cutscene.shots.length} shots · {cutscene.trigger}</small></span></button>)}</aside>{selected ? <><section className="cutscene-board"><div className="cutscene-tools"><Field label="Sequence title"><input value={selected.title} onChange={(event) => updateCutscene({ title: event.target.value })} /></Field><Field label="Starts when"><select value={selected.trigger} onChange={(event) => updateCutscene({ trigger: event.target.value as Cutscene["trigger"] })}><option value="manual">manually played</option><option value="room-entry">a room opens</option><option value="story-node">a story node opens</option></select></Field><button className="outline-button" onClick={() => onPreview(selected.id)}><Play size={15} /> Preview cutscene</button></div><div className="shot-reel">{selected.shots.map((candidate, index) => <button key={candidate.id} className={`shot-card ${shot?.id === candidate.id ? "is-current" : ""}`} onClick={() => setShotId(candidate.id)}><span>0{index + 1}</span><i className={`shot-frame ${candidate.camera}`} /><b>{candidate.label}</b><small>{candidate.duration.toFixed(1)}s · {candidate.transition}</small></button>)}<button className="add-shot-card" onClick={addShot}><Plus size={17} /> Add shot</button></div><div className="cutscene-timeline">{selected.shots.map((candidate) => <div key={candidate.id} style={{ width: `${Math.max(14, candidate.duration * 16)}%` }} className="cut-beat"><b>{candidate.label}</b><small>{candidate.duration}s</small></div>)}</div></section><aside className="shot-inspector">{shot ? <><div className="panel-label"><span>Shot editor</span><TinyButton tone="danger" title="Delete shot" onClick={() => { updateCutscene({ shots: selected.shots.filter((candidate) => candidate.id !== shot.id) }); setShotId(selected.shots.find((candidate) => candidate.id !== shot.id)?.id); }}><Trash2 size={14} /></TinyButton></div><Field label="Shot label"><input value={shot.label} onChange={(event) => updateShot({ label: event.target.value })} /></Field><Field label="Room"><select value={shot.roomId} onChange={(event) => updateShot({ roomId: event.target.value })}>{project.rooms.map((room) => <option value={room.id} key={room.id}>{room.name}</option>)}</select></Field><div className="inline-fields"><Field label="Frame"><select value={shot.camera} onChange={(event) => updateShot({ camera: event.target.value as CutsceneShot["camera"] })}>{["wide", "medium", "close", "detail"].map((camera) => <option value={camera} key={camera}>{camera}</option>)}</select></Field><Field label="Transition"><select value={shot.transition} onChange={(event) => updateShot({ transition: event.target.value as CutsceneShot["transition"] })}>{["cut", "fade", "dissolve", "hold"].map((transition) => <option value={transition} key={transition}>{transition}</option>)}</select></Field></div><Field label="Duration (seconds)"><input type="number" min="0.2" step="0.1" value={shot.duration} onChange={(event) => updateShot({ duration: Number(event.target.value) })} /></Field><Field label="Speaker"><input value={shot.speaker} onChange={(event) => updateShot({ speaker: event.target.value })} /></Field><Field label="Subtitle / direction"><textarea value={shot.line} onChange={(event) => updateShot({ line: event.target.value })} /></Field></> : <div className="inspector-empty"><Clapperboard size={26} /><b>Add the first shot.</b><p>A cutscene is built from rooms, camera frames, transitions and optional subtitles.</p></div>}</aside></> : <section className="cutscene-empty"><Film size={34} /><h2>Your story deserves a breath between moments.</h2><p>Create a cutscene, then add shots from your authored rooms.</p></section>}</section></main>;
}

