function ScriptsPanel({ project, update, onGoToStory }: { project: LumenProject; update: (next: LumenProject) => void; onGoToStory: () => void }) {
  const allElements = project.rooms.flatMap((room) => room.elements.map((element) => ({ ...element, roomName: room.name })));
  const [selectedId, setSelectedId] = useState<string | undefined>(project.behaviours[0]?.id);
  const selected = project.behaviours.find((program) => program.id === selectedId) ?? project.behaviours[0];
  const [luaDraft, setLuaDraft] = useState("");
  const [luaErrors, setLuaErrors] = useState<string[]>([]);
  useEffect(() => { setLuaDraft(selected ? blocksToLua(selected) : ""); setLuaErrors([]); }, [selected?.id]);

  const updateProgram = (patch: Partial<NonNullable<typeof selected>>) => {
    if (!selected) return;
    update({ ...project, behaviours: project.behaviours.map((program) => program.id === selected.id ? { ...program, ...patch } : program) });
  };
  const targetsFor = (kind: BehaviourBlockKind) => {
    if (kind === "set_state" || kind === "add_number") return project.variables.map((variable) => ({ id: variable.key, label: variable.key }));
    if (kind === "give_item") return project.items.map((item) => ({ id: item.id, label: item.name }));
    if (kind === "open_story") return project.narrative.map((node) => ({ id: node.id, label: node.title }));
    if (kind === "move_room") return project.rooms.map((room) => ({ id: room.id, label: room.name }));
    return project.cutscenes.map((cutscene) => ({ id: cutscene.id, label: cutscene.title }));
  };
  const createProgram = () => {
    const program = createBehaviourProgram(allElements[0]?.id ?? "");
    program.label = "New interactive behaviour";
    update({ ...project, behaviours: [...project.behaviours, program] });
    setSelectedId(program.id);
  };
  const createBlock = (kind: BehaviourBlockKind) => {
    if (!selected) return;
    const first = targetsFor(kind)[0];
    updateProgram({ blocks: [...selected.blocks, { id: makeId("block"), kind, target: first?.id ?? "", value: kind === "set_state" ? "true" : kind === "add_number" ? "1" : "", condition: "" }] });
  };
  const syncLuaToBlocks = () => {
    if (!selected) return;
    const parsed = parseSupportedLua(luaDraft);
    if (!parsed.program) { setLuaErrors(parsed.errors); return; }
    updateProgram({ ...parsed.program, id: selected.id, label: selected.label });
    setLuaErrors([]);
    toast.success("Supported Lua synchronised to visual blocks.");
  };
  if (!selected) return <main className="creator-page scripts-page"><section className="page-heading"><div><span className="eyebrow">Behaviour workspace · Lua and visual blocks</span><h1>Make an object do something.</h1></div><button className="amber-button" onClick={createProgram}><Plus size={16} /> New behaviour</button></section><section className="logic-empty"><Code2 size={30} /><h2>Give a prop a memory.</h2><p>Attach a behaviour to a scene element, then compose it from state, story, room and cutscene blocks.</p></section></main>;
  const luaFromBlocks = blocksToLua(selected);
  return <main className="creator-page scripts-page">
    <section className="page-heading"><div><span className="eyebrow">Behaviour workspace · Lua and visual blocks</span><h1>One small language, two ways to think.</h1></div><button className="amber-button" onClick={createProgram}><Plus size={16} /> New behaviour</button></section>
    <section className="script-intro"><Code2 size={23} /><div><b>Blocks and Lua share one safe behaviour model.</b><p>Every supported block generates valid Lumenforge Lua. Applying compatible Lua rebuilds the same blocks. Unsupported freeform Lua is never silently altered or discarded.</p></div></section>
    <section className="logic-layout">
      <aside className="logic-programs"><div className="panel-label"><span>Behaviours</span></div>{project.behaviours.map((program) => <button className={selected.id === program.id ? "is-current" : ""} onClick={() => setSelectedId(program.id)} key={program.id}><Code2 size={14} /><span>{program.label}<small>{allElements.find((element) => element.id === program.elementId)?.label || "unattached"} · {program.blocks.length} blocks</small></span></button>)}</aside>
      <section className="block-editor">
        <div className="logic-header"><Field label="Behaviour name"><input value={selected.label} onChange={(event) => updateProgram({ label: event.target.value })} /></Field><Field label="Runs when this element is clicked"><select value={selected.elementId} onChange={(event) => updateProgram({ elementId: event.target.value })}><option value="">Choose a scene element</option>{allElements.map((element) => <option value={element.id} key={element.id}>{element.roomName} / {element.label}</option>)}</select></Field><TinyButton tone="danger" title="Delete behaviour" onClick={() => { update({ ...project, behaviours: project.behaviours.filter((program) => program.id !== selected.id) }); setSelectedId(project.behaviours.find((program) => program.id !== selected.id)?.id); }}><Trash2 size={14} /></TinyButton></div>
        <div className="block-toolbar"><span>Visual blocks</span><div><button onClick={() => createBlock("set_state")}>Set state</button><button onClick={() => createBlock("add_number")}>Add number</button><button onClick={() => createBlock("give_item")}>Give item</button><button onClick={() => createBlock("open_story")}>Open story</button><button onClick={() => createBlock("move_room")}>Move room</button><button onClick={() => createBlock("play_cutscene")}>Play cutscene</button></div></div>
        <div className="block-canvas"><div className="event-cap">when <b>{allElements.find((element) => element.id === selected.elementId)?.label || "an element"}</b> is clicked</div>{selected.blocks.length === 0 && <p className="empty-copy">Add a block above. Its Lua appears immediately in the source panel.</p>}{selected.blocks.map((block) => <article className={`logic-block block-${block.kind}`} key={block.id}><span>{block.kind === "set_state" ? "set state" : block.kind === "add_number" ? "add number" : block.kind === "give_item" ? "give item" : block.kind === "open_story" ? "open story" : block.kind === "move_room" ? "move room" : "play cutscene"}</span><select value={block.target} onChange={(event) => updateProgram({ blocks: selected.blocks.map((candidate) => candidate.id === block.id ? { ...candidate, target: event.target.value } : candidate) })}><option value="">Choose target</option>{targetsFor(block.kind).map((target) => <option value={target.id} key={target.id}>{target.label}</option>)}</select>{(block.kind === "set_state" || block.kind === "add_number") && <input value={block.value ?? ""} onChange={(event) => updateProgram({ blocks: selected.blocks.map((candidate) => candidate.id === block.id ? { ...candidate, value: event.target.value } : candidate) })} placeholder={block.kind === "set_state" ? "true / false / text" : "1"} />}<input value={block.condition ?? ""} onChange={(event) => updateProgram({ blocks: selected.blocks.map((candidate) => candidate.id === block.id ? { ...candidate, condition: event.target.value } : candidate) })} placeholder="optional condition" /><button onClick={() => updateProgram({ blocks: selected.blocks.filter((candidate) => candidate.id !== block.id) })} title="Delete block"><X size={13} /></button></article>)}</div>
      </section>
      <section className="lua-editor"><div className="panel-label"><span>Lua source · supported subset</span><button className="text-button" onClick={() => { setLuaDraft(luaFromBlocks); setLuaErrors([]); }}>Use blocks</button></div><textarea value={luaDraft} onChange={(event) => setLuaDraft(event.target.value)} spellCheck="false" aria-label="Lua source editor" /><div className="lua-actions"><button className="amber-button" onClick={syncLuaToBlocks}><Check size={14} /> Apply Lua to blocks</button><button className="outline-button" onClick={onGoToStory}><MessageCircle size={14} /> Story nodes</button></div>{luaErrors.length > 0 ? <div className="lua-errors"><b>Not applied — your blocks were kept safe.</b>{luaErrors.map((error) => <span key={error}>{error}</span>)}</div> : <div className="lua-ok"><Check size={14} /> This source maps to {selected.blocks.length} visual block(s).</div>}</section>
    </section>
    <section className="script-boundary"><Lightbulb size={18} /><p><strong>Supported Lua commands:</strong> `state.set`, `state.add`, `story.open`, `room.open`, `cutscene.play`, and optional `if state.test("condition") then` guards. This bounded grammar is what makes two-way conversion reliable without pretending that all Lua has a visual-block equivalent.</p></section>
  </main>;
}

function BuildPanel({ project, onPreview, onExport, onGameExport, releaseEvidence }: { project: LumenProject; onPreview: () => void; onExport: () => void; onGameExport: (data: unknown, name: string) => void; releaseEvidence: ReleaseEvidence }) {
  const validation = validateProject(project); const hasPlayableStart = Boolean(getActiveRoom(project)?.entryNode || project.narrative.some((node) => node.kind === "start"));
  const verifiedBundle = releaseEvidence.bundleSha256 !== "not-generated";
  const packageData = { format: "lumenforge-worldbuilder-game-package", version: "0.3", generatedAt: new Date().toISOString(), postProcessing: project.build.postProcessing, provenance: releaseEvidence, project };
  const gamePackage = () => onGameExport(packageData, project.build.executableName);
  return <main className="creator-page build-page"><section className="page-heading"><div><span className="eyebrow">Release workshop · Worldbuilder lineage</span><h1>Make the story ready to leave the worktable.</h1></div><button className="amber-button" onClick={gamePackage}><Download size={16} /> Export game package</button></section><section className="release-layout"><article className="release-card release-identity"><div className="card-title"><Gamepad2 size={16} /><span>Windows game identity</span></div><b>{project.build.executableName}.exe</b><p>The executable name travels with the release configuration. The game package includes all project data and its post-processing intent.</p><div className="release-tags"><span>Windows x64</span><span>offline project data</span><span>procedural visuals</span></div></article><article className="release-card"><div className="card-title"><Sparkles size={16} /><span>Build proof</span></div><p><strong>{DESKTOP_RELEASE}</strong><br />source {releaseEvidence.sourceRevision}<br />bundle {verifiedBundle ? releaseEvidence.bundleSha256.slice(0, 16) : "awaiting production build"}<br />native {releaseEvidence.nativeSourceRevision}</p><div className="release-tags"><span>{releaseEvidence.buildChannel}</span><span>{verifiedBundle ? "manifest present" : "development build"}</span></div></article><article className="release-card readiness"><div className="card-title"><Workflow size={16} /><span>Release readiness</span></div><b>{validation.score}<small>/100</small></b><p>{validation.errors.length ? `${validation.errors.length} issue(s) stop release packaging.` : hasPlayableStart ? "Your project has a playable entry route." : "Add an entry route before packaging."}</p></article></section><section className="release-gates">{[["Project integrity", validation.errors.length === 0, validation.errors.length ? validation.errors[0] : "All references resolve locally."], ["Playable entry", hasPlayableStart, hasPlayableStart ? "A preview can begin from the active room." : "Choose an entry node for the active room."], ["Worldbuilder provenance", verifiedBundle, verifiedBundle ? `Bundle ${releaseEvidence.bundleSha256.slice(0, 16)}… is recorded in the packaged manifest.` : "Create a production build to emit its bundle fingerprint."], ["Windows executable", false, "Requires the bundled native game-player adapter and a Windows packaging toolchain."]].map(([title, passes, detail]) => <article key={title as string}><span className={passes ? "gate-pass" : "gate-wait"}>{passes ? <Check size={16} /> : <Settings2 size={16} />}</span><div><b>{title as string}</b><p>{detail as string}</p></div><em>{passes ? "clear" : "toolchain"}</em></article>)}</section><section className="build-actions"><button className="outline-button" onClick={onPreview}><Play size={15} /> Run local playtest</button><button className="outline-button" onClick={onExport}><FileCode2 size={15} /> Export editable project</button></section><section className="honest-release-note"><BookOpen size={18} /><p><strong>What works now:</strong> a portable game package is created locally and carries your rooms, elements, dialogue, cutscenes, state, display treatments, and build provenance. <strong>What the Windows adapter must still do:</strong> embed that package into the dedicated player runtime and compile it into the final `.exe`; the in-app release gate deliberately keeps this distinction visible.</p></section></main>;
}

function PreviewPlayer({ project, onClose, onProjectChange, cutsceneId }: { project: LumenProject; onClose: () => void; onProjectChange: (project: LumenProject) => void; cutsceneId?: string }) {
  const [runtime, setRuntime] = useState<LumenProject>(() => structuredClone(project)); const initialRoom = getActiveRoom(project); const [roomId, setRoomId] = useState(initialRoom.id); const [nodeId, setNodeId] = useState(initialRoom.entryNode || project.narrative.find((node) => node.kind === "start")?.id || ""); const [activeCutscene, setActiveCutscene] = useState(cutsceneId); const [shotIndex, setShotIndex] = useState(0); const [notice, setNotice] = useState("");
  const [animationStarts, setAnimationStarts] = useState<Record<string, number>>({}); const [animationNow, setAnimationNow] = useState(0);
  useEffect(() => { if (!Object.keys(animationStarts).length) return; const timer = window.setInterval(() => setAnimationNow(performance.now()), 33); return () => window.clearInterval(timer); }, [animationStarts]);
  const motion = useMemo(() => { const output: Record<string, RuntimeMotion> = {}; runtime.animations.forEach((clip) => { const started = animationStarts[clip.id]; if (!started) return; let seconds = (animationNow - started) / 1000; if (seconds > clip.duration && !clip.loop) return; if (clip.loop) seconds %= clip.duration; output[clip.targetId] = Object.fromEntries(clip.tracks.map((track) => [track.property, sampleTrack(track, seconds)])); }); return output; }, [runtime.animations, animationStarts, animationNow]);
  const room = runtime.rooms.find((candidate) => candidate.id === roomId) ?? runtime.rooms[0]; const node = runtime.narrative.find((candidate) => candidate.id === nodeId); const cutscene = runtime.cutscenes.find((candidate) => candidate.id === activeCutscene); const shot = cutscene?.shots[shotIndex]; const clickableAnimationTargets = useMemo(() => new Set(runtime.animations.filter((clip) => clip.trigger === "click").map((clip) => clip.targetId)), [runtime.animations]);
  const setRuntimeAndPersist = (next: LumenProject) => { setRuntime(next); onProjectChange(next); };
  const goToNode = (target: string, effect?: string, base = runtime) => { let next = applyEffect(base, effect); const destination = next.narrative.find((candidate) => candidate.id === target); if (!destination) { setRuntimeAndPersist(next); return; } if (!conditionPasses(next, destination.condition)) { setNotice("That path is still waiting for a different fact."); return; } next = applyEffect(next, destination.effect); setRuntimeAndPersist(next); setNodeId(destination.id); setNotice(""); };
  const activateElement = (element: SceneElement) => { const matchingAnimations = runtime.animations.filter((clip) => clip.targetId === element.id && clip.trigger === "click"); if (matchingAnimations.length) { const now = performance.now(); setAnimationNow(now); setAnimationStarts((current) => ({ ...current, ...Object.fromEntries(matchingAnimations.map((clip) => [clip.id, now])) })); setNotice(`${matchingAnimations.map((clip) => clip.label).join(" · ")} started`); } if (!conditionPasses(runtime, element.interaction.condition)) return setNotice("That interaction is not available yet."); let base = structuredClone(runtime); const messages: string[] = []; if (element.collectibleItemId && !base.inventory.itemIds.includes(element.collectibleItemId)) { if (base.inventory.itemIds.length >= base.inventory.maxSlots) return setNotice("The inventory is full."); const item = base.items.find((candidate) => candidate.id === element.collectibleItemId); if (item) { base.inventory.itemIds.push(item.id); messages.push(`${item.name} collected`); } } const scripted = runBehaviour(base, element.id); const notice = [...messages, ...scripted.messages].join(" · "); if (scripted.storyId) return goToNode(scripted.storyId, undefined, scripted.project); if (scripted.roomId) { const destination = scripted.project.rooms.find((candidate) => candidate.id === scripted.roomId); if (destination) { setRuntimeAndPersist(scripted.project); setRoomId(destination.id); setNodeId(destination.entryNode); setNotice(notice); return; } } if (scripted.cutsceneId) { setRuntimeAndPersist(scripted.project); setActiveCutscene(scripted.cutsceneId); setShotIndex(0); return; } if (element.interaction.type === "story") return goToNode(element.interaction.target, undefined, scripted.project); if (element.interaction.type === "room") { const destination = scripted.project.rooms.find((candidate) => candidate.id === element.interaction.target); if (destination) { setRuntimeAndPersist(scripted.project); setRoomId(destination.id); setNodeId(destination.entryNode); setNotice(notice); } } if (element.interaction.type === "cutscene") { setRuntimeAndPersist(scripted.project); setActiveCutscene(element.interaction.target); setShotIndex(0); } else if (notice) { setRuntimeAndPersist(scripted.project); setNotice(notice); } };
  const continueStory = () => { if (!node) return; if (node.target) goToNode(node.target); else setNotice("This moment has no continuation yet. Add one in Story."); };
  const restart = () => { const next = structuredClone(project); setRuntime(next); const startRoom = getActiveRoom(next); setRoomId(startRoom.id); setNodeId(startRoom.entryNode || next.narrative.find((candidate) => candidate.kind === "start")?.id || ""); setActiveCutscene(undefined); setNotice(""); };
  if (cutscene && shot) return <div className="preview-overlay" role="dialog" aria-modal="true"><section className="preview-window cutscene-preview"><header><div><Monogram /><span>Cutscene preview</span><small>{cutscene.title} · shot {shotIndex + 1} of {cutscene.shots.length}</small></div><button onClick={onClose} aria-label="Close preview"><X size={18} /></button></header><div className={`cutscene-stage camera-${shot.camera} transition-${shot.transition}`}><SceneCanvas room={runtime.rooms.find((candidate) => candidate.id === shot.roomId) ?? room} playable /><div className="cutscene-letterbox top" /><div className="cutscene-letterbox bottom" />{shot.line && <div className="cutscene-subtitle"><small>{shot.speaker || "DIRECTION"}</small><p>{shot.line}</p></div>}</div><footer><span>{shot.camera} frame · {shot.transition} · {shot.duration.toFixed(1)} seconds</span><button className="amber-button" onClick={() => shotIndex < cutscene.shots.length - 1 ? setShotIndex((index) => index + 1) : setActiveCutscene(undefined)}>{shotIndex < cutscene.shots.length - 1 ? "Next shot" : "Enter story"} <ChevronRight size={15} /></button></footer></section></div>;
  return <div className="preview-overlay" role="dialog" aria-modal="true"><section className="preview-window"><header><div><Monogram /><span>Playable preview</span><small>{runtime.title} · local runtime</small></div><button onClick={onClose} aria-label="Close preview"><X size={18} /></button></header><div className="preview-stage"><SceneCanvas room={room} playable onActivate={activateElement} animatedIds={clickableAnimationTargets} motion={motion} /><div className="preview-hint">Click glowing interactive elements in the scene.</div>{node && <div className="runtime-dialogue"><div className="portrait-disc">{(node.speaker || "?").slice(0, 1).toUpperCase()}</div><div><small>{node.speaker || "NARRATOR"}</small><p>{node.body || "This node has no text yet."}</p>{node.kind === "choice" && <div className="runtime-choices">{node.choices.filter((choice) => conditionPasses(runtime, choice.condition)).map((choice) => <button key={choice.id} onClick={() => goToNode(choice.target, choice.effect)}>{choice.text || "Untitled choice"}<ChevronRight size={14} /></button>)}{node.choices.length === 0 && <span>No choices have been authored for this node.</span>}</div>}<div className="runtime-actions">{node.kind === "choice" ? <button onClick={restart}><Play size={14} /> Restart</button> : node.kind === "ending" ? <button onClick={restart}><Play size={14} /> Replay project</button> : <button onClick={continueStory}>Continue <ChevronRight size={14} /></button>}<span>{notice || (node.effect ? `effect: ${node.effect}` : `node: ${node.title}`)}</span></div></div></div>}</div></section></div>;
}

function Onboarding({ onClose, onNavigate }: { onClose: () => void; onNavigate: (mode: ScreenMode) => void }) {
  const [step, setStep] = useState(0); const steps: Array<{ eyebrow: string; title: string; body: string; mode: ScreenMode; label: string; icon: LucideIcon }> = [
    { eyebrow: "First light · 1 of 4", title: "Begin with one room, not a universe.", body: "Create a room, choose its atmosphere, then add a lamp, door or character from the procedural Scene Kit.", mode: "room", label: "Open Rooms", icon: Aperture },
    { eyebrow: "Cause and effect · 2 of 4", title: "Give one thing a consequence.", body: "Connect a prop to a story node, write a choice, and set one small state effect such as lamp_awake = true.", mode: "narrative", label: "Open Story", icon: MessageCircle },
    { eyebrow: "Direction · 3 of 4", title: "Cut to the feeling, not the explanation.", body: "Use Cutscene to place the authored room in a wide, medium or close shot; add a short subtitle if the silence needs help.", mode: "cutscene", label: "Open Cutscene", icon: Film },
    { eyebrow: "Play it · 4 of 4", title: "Preview before you perfect it.", body: "The preview runs the current local project. Export keeps an editable JSON copy and a release package for the Windows player adapter.", mode: "build", label: "Open Export", icon: Gamepad2 },
  ]; const current = steps[step]; const Icon = current.icon;
  return <div className="onboarding-overlay"><section className="onboarding-card"><button className="onboarding-close" onClick={onClose} aria-label="Skip tutorial"><X size={17} /></button><div className="onboarding-visual"><Monogram /><Icon size={31} /><i /><i /><i /></div><span className="eyebrow">{current.eyebrow}</span><h2>{current.title}</h2><p>{current.body}</p><div className="onboarding-actions"><button className="text-button" onClick={onClose}>Skip for now</button><span>{steps.map((_, index) => <i key={index} className={index === step ? "is-active" : ""} />)}</span><button className="amber-button" onClick={() => { onNavigate(current.mode); if (step === steps.length - 1) onClose(); else setStep((index) => index + 1); }}>{current.label} <ArrowRight size={15} /></button></div></section></div>;
}

function NewProjectDialog({ projectMode, onCancel, onCreate }: { projectMode: ProjectMode; onCancel: () => void; onCreate: (title: string) => void }) {
  const [title, setTitle] = useState(projectMode === "3d" ? "Untitled 3D Lantern" : "Untitled Lantern");
  return <div className="onboarding-overlay" role="dialog" aria-modal="true" aria-label="Create project"><section className="new-project-card"><button className="onboarding-close" onClick={onCancel} aria-label="Cancel new project"><X size={17} /></button><div className="new-project-mode"><Layers3 size={24} /><span>{projectMode.toUpperCase()} NARRATIVE</span></div><h2>Create a blank {projectMode === "3d" ? "3D" : "2D"} world.</h2><p>{projectMode === "3d" ? "Begin with procedural primitives, lights, cameras, terrain and a local 3D renderer. Story and state remain compatible." : "Begin with the paper-stage room editor, procedural elements and cinematic narrative tooling."}</p><Field label="Project title"><input autoFocus value={title} onChange={(event) => setTitle(event.target.value)} onKeyDown={(event) => { if (event.key === "Enter") onCreate(title); }} /></Field><div className="new-project-actions"><button className="outline-button" onClick={onCancel}>Cancel</button><button className="amber-button" onClick={() => onCreate(title)}>Create {projectMode.toUpperCase()} project <ArrowRight size={15} /></button></div></section></div>;
}

export default function Home() {
  const [mode, setMode] = useState<ScreenMode>("project"); const [project, setProject] = useState<LumenProject>(() => loadLocalProject()); const [selectedElementId, setSelectedElementId] = useState<string>(); const [selectedNodeId, setSelectedNodeId] = useState<string>(); const [preview, setPreview] = useState<{ open: boolean; cutsceneId?: string }>({ open: false }); const [splash, setSplash] = useState(true); const [onboarding, setOnboarding] = useState(() => !window.localStorage.getItem("lumenforge.worldbuilder.onboarding.v4.complete")); const [newProjectMode, setNewProjectMode] = useState<ProjectMode | null>(null); const [releaseEvidence, setReleaseEvidence] = useState<ReleaseEvidence>(initialReleaseEvidence); const importRef = useRef<HTMLInputElement>(null);
  useEffect(() => { const timer = window.setTimeout(() => setSplash(false), 680); return () => window.clearTimeout(timer); }, []);
  useEffect(() => { saveLocalProject(project); }, [project]);
  useEffect(() => { void (async () => { let verification: Partial<ReleaseEvidence> = {}; let native: Partial<ReleaseEvidence> = {}; try { const response = await fetch("/worldbuilder-verification.json", { cache: "no-store" }); if (response.ok) { const manifest = await response.json() as { sourceRevision?: string; bundleSha256?: string; generatedAt?: string }; verification = { sourceRevision: manifest.sourceRevision, bundleSha256: manifest.bundleSha256, generatedAt: manifest.generatedAt }; } } catch { /* Development preview intentionally has no production manifest. */ } try { const { invoke } = await import("@tauri-apps/api/core"); const status = await invoke<{ sourceRevision?: string; buildChannel?: string }>("desktop_status"); native = { nativeSourceRevision: status.sourceRevision, buildChannel: status.buildChannel }; } catch { /* Browser preview is a supported development host. */ } setReleaseEvidence((current) => ({ ...current, ...verification, ...native })); })(); }, []);
  useEffect(() => { const listener = (event: KeyboardEvent) => { const item = nav.find((candidate) => candidate.shortcut === event.key); if (item && !event.metaKey && !event.ctrlKey && !event.altKey) setMode(item.id); }; window.addEventListener("keydown", listener); return () => window.removeEventListener("keydown", listener); }, []);
  const updateProject = (next: LumenProject) => setProject({ ...next, updatedAt: new Date().toISOString() });
  const patchProject = (patch: Partial<LumenProject>) => updateProject({ ...project, ...patch });
  const newEmpty = (projectMode: ProjectMode, title: string) => { const next = createEmptyProject(title.trim() || (projectMode === "3d" ? "Untitled 3D Lantern" : "Untitled Lantern"), projectMode); updateProject(next); setMode(projectMode === "3d" ? "threeD" : "project"); setSelectedElementId(undefined); setSelectedNodeId(undefined); setNewProjectMode(null); toast.success(`A clean ${projectMode.toUpperCase()} local project is ready for its first scene.`); };
  const loadStarter = () => { if (!window.confirm("Replace the current project with the editable starter project in this project mode? Export first if you need a copy.")) return; const next = createStarterProject(project.mode); updateProject(next); setMode(project.mode === "3d" ? "threeD" : "room"); setSelectedElementId(next.rooms[0]?.elements[0]?.id); toast.success("Starter project loaded. Every item in it is editable."); };
  const addRoom = () => { const name = window.prompt("Name the new room", `Room ${project.rooms.length + 1}`); if (!name) return; const room: LumenRoom = { id: makeId("room"), name, mark: String(project.rooms.length + 1).padStart(2, "0"), ambience: "afterhours", entryNode: "", elements: [] }; updateProject({ ...project, rooms: [...project.rooms, room], activeRoom: room.id }); setSelectedElementId(undefined); toast.success(`${name} added to the project.`); };
  const duplicateRoom = () => { const room = getActiveRoom(project); const copy: LumenRoom = { ...structuredClone(room), id: makeId("room"), name: `${room.name} copy`, mark: String(project.rooms.length + 1).padStart(2, "0"), elements: room.elements.map((element) => ({ ...element, id: makeId(element.kind), x: Math.min(92, element.x + 3) })) }; updateProject({ ...project, rooms: [...project.rooms, copy], activeRoom: copy.id }); setSelectedElementId(undefined); toast.success("Room duplicated with its elements and interactions."); };
  const deleteRoom = () => { const room = getActiveRoom(project); if (project.rooms.length < 2) return toast.error("A project needs at least one room."); if (!window.confirm(`Remove “${room.name}”? Elements inside it will be removed.`)) return; const rooms = project.rooms.filter((candidate) => candidate.id !== room.id); updateProject({ ...project, rooms, activeRoom: rooms[0].id }); setSelectedElementId(undefined); };
  const exportProject = () => { downloadJson(`${project.id}.lumenforge.json`, project); toast.success("Editable project JSON exported locally."); };
  const exportGamePackage = async (data: unknown, name: string) => { try { const { invoke } = await import("@tauri-apps/api/core"); const result = await invoke<string>("export_game_package", { content: JSON.stringify(data), exportName: name }); toast.success(result); } catch { downloadJson(`${name}.lumenforge-game.json`, data); toast.success("Validated portable game package downloaded. Desktop export will save directly to Documents when run inside Lumenforge for Windows."); } };
  const importProject = async (event: ChangeEvent<HTMLInputElement>) => { const file = event.target.files?.[0]; if (!file) return; try { const parsed = JSON.parse(await file.text()); if (parsed.schemaVersion !== "4.0" || !Array.isArray(parsed.rooms) || !Array.isArray(parsed.narrative)) throw new Error("schema"); updateProject(parsed as LumenProject); setMode("project"); toast.success("Editable Lumenforge Worldbuilder 0.4 project loaded."); } catch { toast.error("This file is not a compatible Worldbuilder 0.4 project."); } finally { event.target.value = ""; } };
  const content = useMemo(() => ({
    project: <ProjectPanel project={project} update={patchProject} onEmpty={setNewProjectMode} onStarter={loadStarter} onImport={() => importRef.current?.click()} onExport={exportProject} onOpenRooms={() => setMode("room")} />,
    room: <RoomPanel project={project} update={updateProject} selectedId={selectedElementId} setSelectedId={setSelectedElementId} onAddRoom={addRoom} onDuplicateRoom={duplicateRoom} onDeleteRoom={deleteRoom} />,
    inventory: <InventoryPanel project={project} update={updateProject} onOpenRooms={() => setMode("room")} />,
    narrative: <NarrativePanel project={project} update={updateProject} selectedId={selectedNodeId} setSelectedId={setSelectedNodeId} onPreview={() => setPreview({ open: true })} />,
    state: <StatePanel project={project} update={updateProject} />,
    cutscene: <CutscenePanel project={project} update={updateProject} onPreview={(cutsceneId) => setPreview({ open: true, cutsceneId })} />,
    scripts: <ScriptsPanel project={project} update={updateProject} onGoToStory={() => setMode("narrative")} />,
    animation: <AnimationPanel project={project} update={updateProject} />,
    diy: <DiyPanel project={project} update={updateProject} />,
    threeD: <ThreeDPanel project={project} update={updateProject} />,
    advanced: <AdvancedToolsPanel project={project} update={updateProject} />,
    build: <BuildPanel project={project} onPreview={() => setPreview({ open: true })} onExport={exportProject} onGameExport={exportGamePackage} releaseEvidence={releaseEvidence} />,
  }), [project, selectedElementId, selectedNodeId, releaseEvidence]);
  const dismissOnboarding = () => { window.localStorage.setItem("lumenforge.worldbuilder.onboarding.v4.complete", "true"); setOnboarding(false); };
  return <div className="lumen-v2" data-release={DESKTOP_RELEASE}><header className="topbar"><div className="brand-lockup"><Monogram /><div><strong>LUMENFORGE</strong><span>worldbuilder / local-first</span></div></div><div className="project-switcher"><FolderOpen size={15} /><b>{project.title}</b><span className="project-badge">{project.mode.toUpperCase()} · {DESKTOP_RELEASE}</span></div><div className="top-actions"><span className="autosave"><i /> Saved locally</span><button className="quiet-action" onClick={() => { saveLocalProject(project); toast.success("Project saved locally."); }}><Save size={15} /> Save</button><button className="quiet-action" onClick={() => setOnboarding(true)}><HelpCircle size={15} /> Guide</button><button className="preview-action" onClick={() => setPreview({ open: true })}><Play size={14} fill="currentColor" /> Preview</button><button className="export-action" onClick={exportProject}><Download size={15} /> Export</button></div></header><div className="workspace-shell"><nav className="tool-rail"><div className="rail-main">{nav.map((item) => <RailButton key={item.id} item={item} active={mode === item.id} onClick={() => setMode(item.id)} />)}</div><div className="rail-bottom"><button className="rail-icon" title="New project" onClick={() => setNewProjectMode("2d")}><FilePlus2 size={18} /></button><button className="rail-icon" title="Project settings" onClick={() => setMode("project")}><Settings2 size={18} /></button></div></nav><section className={`creator-surface screen-${mode}`}>{content[mode]}</section></div><footer className="statusbar"><span><i /> Worldbuilder model 4.0 · {project.mode.toUpperCase()}</span><span><Layers3 size={14} /> {project.rooms.reduce((total, room) => total + room.elements.length, 0)} scene elements · {project.threeD.objects.length} 3D objects</span><span><Film size={14} /> {project.cutscenes.reduce((total, cutscene) => total + cutscene.shots.length, 0)} directed shots · {project.animations.length} motion clips</span><span className="statusbar-right">{DESKTOP_RELEASE} · revision {releaseEvidence.sourceRevision} · offline by design</span></footer><input ref={importRef} className="visually-hidden" type="file" accept="application/json,.json" onChange={importProject} />{preview.open && <PreviewPlayer project={project} onClose={() => setPreview({ open: false })} onProjectChange={updateProject} cutsceneId={preview.cutsceneId} />}{newProjectMode && <NewProjectDialog projectMode={newProjectMode} onCancel={() => setNewProjectMode(null)} onCreate={(title) => newEmpty(newProjectMode, title)} />}{splash && <div className="startup-splash"><Monogram /><span>LUMENFORGE</span><i /></div>}{onboarding && !splash && <Onboarding onClose={dismissOnboarding} onNavigate={setMode} />}</div>;
}
